CREATE POLICY "operator_manage" ON "dms"."document_grant" AS PERMISSIVE FOR ALL TO "thaarei_dms_operator" USING (tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid AND current_setting('app.principal_kind',true)='operator' AND EXISTS(SELECT 1 FROM dms.operator_authorization WHERE tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid AND subject_id=current_setting('app.actor_id',true) AND revoked_at IS NULL)) WITH CHECK (tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid AND current_setting('app.principal_kind',true)='operator' AND EXISTS(SELECT 1 FROM dms.operator_authorization WHERE tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid AND subject_id=current_setting('app.actor_id',true) AND revoked_at IS NULL));--> statement-breakpoint
